window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-419ee463deff4e8a"]={"versions": [{"id": "FIG-419ee463deff4e8a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong> (Scope: <em>per compiler platform</em>): Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong> (Scope: <em>per build environment</em>): Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong> (Scope: <em>per component and build environment</em>): Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong> (Scope: <em>per build environment</em>): Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene, z. B. <code>CODE</code>, <code>VAR_CLEARED_BOOLEAN</code>).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..<em>] bzw. [1..</em>] (präzise Code- und Datensektionen eines BSW-Moduls).</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_memmap.h</code> [1] und <code>+memmap.h</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_memmap.h</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1..*] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+memmap.h</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Plattform-Definition:</strong> Einmalige Definition der Zielcompiler-Eigenschaften (<code>Define Memory Addressing Modes</code>) liefert <code>MemMapAddressingModeSet</code>.</li>\n<li><strong>ECU-Projektierung:</strong> <code>Configure Memmap Allocation</code> aggregiert die <code>SwAddrMethod</code>-Definitionen (SWC) und <code>MemorySection</code>-Definitionen (BSW) und verknüpft diese mit dem <code>MemMapAddressingModeSet</code> zu konkreten <code>MemMapAllocation</code>-Instanzen in den ECU Configuration Values.</li>\n<li><strong>Divergierende Codegenerierung (Build-Vorbereitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>SWC-Pfad:</em> Pro atomarer Software-Komponente wird via <code>Generate SWC Memory Mapping Header</code> eine dedizierte <code>&lt;SWC&gt;_MemMap.h</code> generiert.</li>\n<li><em>BSW-Pfad:</em> Das BSW-Generator-Framework erzeugt via <code>Generate BSW Memory Mapping Header</code> die modulübergreifende <code>MemMap.h</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kompilierung (Build-Phase):</strong> Der C-Präprozessor löst während der Übersetzung von SWC- und BSW-Quellcode die Mapping-Makros über die eingebundenen Header auf Linker-Sektionen auf.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-caba56490913b701", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong> (Scope: <em>Per compiler platform</em>): Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong> (Scope: <em>Per build environment.</em>): Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong> (Scope: <em>Per component and build environment.</em>): Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong> (Scope: <em>Per BSW module/cluster and build environment.</em>): Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-15345da2cd591897", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong> (Scope: <em>Per compiler platform</em>): Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong> (Scope: <em>Per build environment.</em>): Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong> (Scope: <em>Per component and build environment.</em>): Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong> (Scope: <em>Per BSW module/cluster and build environment.</em>): Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-3fb1182b897b3dfc", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong> (Scope: <em>Per compiler platform</em>): Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong> (Scope: <em>Per build environment.</em>): Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong> (Scope: <em>Per component and build environment.</em>): Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong> (Scope: <em>Per BSW module/cluster and build environment.</em>): Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-e6c0cf576be2ce12", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong>: Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong>: Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong>: Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong>: Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-eed4391a0ca78d33", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong>: Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong>: Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong>: Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong>: Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-2e56a58265dad43d", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong>: Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong>: Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong>: Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong>: Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-7999552cc1c10d1f", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong>: Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong>: Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong>: Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong>: Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert optional: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code> <code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*].</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>BSWMD</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus <code>BSWMD</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1]</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1]</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1].</li>\n<li><code>Standard Header Files</code> <code>«input»</code> [1] $\\rightarrow$ Alle Build-Tasks (<code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code>, <code>Compile ECU Source Code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-4d1cb71eee4c80ec", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong>: Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong>: Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong>: Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong>: Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code>:</li>\n<li>Kontext: <code>Per compiler platform</code></li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*] in <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li>Kontext: <code>Per build environment</code></li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*] (aus <code>BSW Module Preconfigured Configuration</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus BSWMD)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li>Kontext: <code>Per component and build environment</code></li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*] (aus <code>BSW Module Preconfigured Configuration</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1] in <code>Standard Header Files</code>.</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li>Kontext: <code>Per BSW module/cluster and build environment</code></li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus BSWMD)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus BSWMD)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*] (aus <code>BSW Module Preconfigured Configuration</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1] in <code>Standard Header Files</code>.</li>\n<li>Downstream-Kompilierung:</li>\n<li><code>Standard Header Files</code> dient als <code>«input»</code> [1] für:</li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}, {"id": "FIG-335b31c7d002a9e6", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> SPEM-2.0-basiertes Prozess- und Datenflussdiagramm (AUTOSAR Methodology Work Product / Activity Flow).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die methodische Kette zur Auflösung und Generierung von Memory-Mapping-Artefakten in der AUTOSAR Classic Platform (R4.0.3). Es modelliert den Übergang von plattformunabhängigen logischen Speicherklassen (<code>SwAddrMethod</code>, <code>MemorySection</code>) zu plattform-, compiler- und linkerspezifischen Header-Dateien (<code>&lt;SWC&gt;_MemMap.h</code>, <code>MemMap.h</code>) für SWCs und BSW-Module vor der Kompilierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Aktivitäten (Methodology Tasks)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Define Memory Addressing Modes</code></strong>: Definiert compiler-spezifische Adressierungsmechanismen und Pragma-Muster.</li>\n<li><strong><code>Configure Memmap Allocation</code></strong>: Weist logische Adressierungsanforderungen konkreten Compiler-Sektionen zu.</li>\n<li><strong><code>Generate SWC Memory Mapping Header</code></strong>: Generiert komponentenspezifische Header für Applikations-SWCs.</li>\n<li><strong><code>Generate BSW Memory Mapping Header</code></strong>: Generiert den zentralen Memory-Mapping-Header für BSW-Module.</li>\n<li><strong>Kompilier-Aktivitäten (Downstream Consumers):</strong></li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<p class=\"fig-p\">#### Work Products (Artefakte & Konfigurationsstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>BSW Module Preconfigured Configuration</code>:</strong></li>\n<li>Enthält: <code>+MemMapAddressingModeSet</code> [1..*] (vordefinierte Satzbeschreibungen für Compiler-Adressierungsarten).</li>\n<li><strong><code>VFB Types</code>:</strong></li>\n<li>Enthält: <code>+SwAddrMethods</code> [0..<em>], <code>+SwAddrMethod</code> [1..</em>] (abstrakte Speicheranforderungen auf VFB-/SWC-Typ-Ebene).</li>\n<li><strong><code>Atomic Software Component Implementation</code>:</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] (Code- und Datensektionen einer SWC-Implementierung).</li>\n<li><strong><code>Basic Software Module Implementation Description</code> (BSWMD):</strong></li>\n<li>Enthält: <code>+MemorySections</code> [0..*] bzw. [1] sowie <code>+DependencyOnArtifact</code> [1].</li>\n<li><strong><code>ECU Configuration Values</code>:</strong></li>\n<li>Enthält: <code>+MemMapAllocation</code> [1] (Zuweisungscontainer im MemMap-Modul).</li>\n<li>Referenziert: <code>+RteImplementationRef</code> [0..1] (für SWC-Instanzen) und <code>+moduleDescription</code> [0..1] (für BSW-Module).</li>\n<li><strong><code>Standard Header Files</code>:</strong></li>\n<li>Enthält generierte C-Header: <code>+SWC_MemMap</code> [1] und <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<p class=\"fig-p\">#### Abhängigkeiten, Rollen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Define Memory Addressing Modes</code>:</li>\n<li>Kontext: <code>Per compiler platform</code></li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAddressingModeSet</code> [1..*] in <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><code>Configure Memmap Allocation</code>:</li>\n<li>Kontext: <code>Per build environment</code></li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*] (aus <code>BSW Module Preconfigured Configuration</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethods</code> [0..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [0..*] (aus BSWMD)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+MemMapAllocation</code> [1] in <code>ECU Configuration Values</code>.</li>\n<li><code>Generate SWC Memory Mapping Header</code>:</li>\n<li>Kontext: <code>Per component and build environment</code></li>\n<li><code>«input»</code> $\\leftarrow$ <code>+SwAddrMethod</code> [1..*] (aus <code>VFB Types</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus <code>Atomic Software Component Implementation</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*] (aus <code>BSW Module Preconfigured Configuration</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+RteImplementationRef</code> [0..1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+SWC_MemMap</code> [1] in <code>Standard Header Files</code>.</li>\n<li><code>Generate BSW Memory Mapping Header</code>:</li>\n<li>Kontext: <code>Per BSW module/cluster and build environment</code></li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemorySections</code> [1] (aus BSWMD)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+DependencyOnArtifact</code> [1] (aus BSWMD)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAddressingModeSet</code> [1..*] (aus <code>BSW Module Preconfigured Configuration</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+MemMapAllocation</code> [1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«input»</code> $\\leftarrow$ <code>+moduleDescription</code> [0..1] (aus <code>ECU Configuration Values</code>)</li>\n<li><code>«output»</code> $\\rightarrow$ <code>+BSW_MemMap</code> [1] in <code>Standard Header Files</code>.</li>\n<li>Downstream-Kompilierung:</li>\n<li><code>Standard Header Files</code> dient als <code>«input»</code> [1] für:</li>\n<li><code>Compile Atomic Software Component</code></li>\n<li><code>Compile BSW Core Code</code></li>\n<li><code>Compile ECU Source Code</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorbereitung Compiler-Adressierungsarten:</strong> <code>Define Memory Addressing Modes</code> erzeugt pro Compilerplattform das Artefakt <code>+MemMapAddressingModeSet</code> [1..*] innerhalb der <code>BSW Module Preconfigured Configuration</code>.</li>\n<li><strong>MemMap-Allokationskonfiguration:</strong> <code>Configure Memmap Allocation</code> aggregiert compiler-spezifische Adressierungsarten (<code>+MemMapAddressingModeSet</code> [1..<em>]) sowie logische Speichersektionsdefinitionen (<code>+SwAddrMethods</code> [0..</em>] aus <code>VFB Types</code>, <code>+MemorySections</code> [0..<em>] aus <code>Atomic Software Component Implementation</code> und <code>+MemorySections</code> [0..</em>] aus <code>Basic Software Module Implementation Description</code>) und erzeugt die Konfiguration <code>+MemMapAllocation</code> [1] innerhalb der <code>ECU Configuration Values</code>.</li>\n<li><strong>Header-Generierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Generate SWC Memory Mapping Header</code> konsumiert <code>+SwAddrMethod</code> [1..<em>], <code>+MemorySections</code> [1] aus der <code>Atomic Software Component Implementation</code>, <code>+MemMapAddressingModeSet</code> [1..</em>], <code>+MemMapAllocation</code> [1] sowie <code>+RteImplementationRef</code> [0..1] und generiert <code>+SWC_MemMap</code> [1].</li>\n<li><code>Generate BSW Memory Mapping Header</code> konsumiert <code>+MemorySections</code> [1], <code>+DependencyOnArtifact</code> [1] aus der <code>BSWMD</code>, <code>+MemMapAddressingModeSet</code> [1..*], <code>+MemMapAllocation</code> [1] sowie <code>+moduleDescription</code> [0..1] und generiert <code>+BSW_MemMap</code> [1].</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Header-Bereitstellung & Kompilierung:</strong> Beide Header gehen als <code>Standard Header Files</code> ein in <code>Compile Atomic Software Component</code>, <code>Compile BSW Core Code</code> und <code>Compile ECU Source Code</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Include-Pattern & Mehrfachinklusion:</strong> <code>MemMap.h</code> und <code>&lt;SWC&gt;_MemMap.h</code> dürfen <strong>keine</strong> klassischen <code>#ifndef</code>-Include-Guards besitzen. Sie werden innerhalb derselben Translation Unit mehrfach re-inkludiert, gesteuert über vorangehende Präprozessor-Makros:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">#define <PREFIX>_START_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">/<em> Code- oder Datendefinition </em>/</p>\n<p class=\"fig-p\">#define <PREFIX>_STOP_SEC_<SECTION_NAME></p>\n<p class=\"fig-p\">#include \"<PREFIX>_MemMap.h\"</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Separation of Concerns (SWC vs. BSW ab R4.0):</strong></li>\n<li>Applikations-SWCs nutzen strikt <code>&lt;SWC&gt;_MemMap.h</code> (verhindert Namespace-Pollution und Build-Flaschenhälse).</li>\n<li>BSW-Module referenzieren direkt <code>MemMap.h</code>.</li>\n<li><strong>Portabilität & Entkopplung:</strong> C-Quelldateien dürfen keine hardcodierten <code>#pragma section</code>-Direktiven enthalten. Die Bindeglieder sind ausschließlich die ARXML-Beschreibungen <code>SwAddrMethod</code> (SWC) und <code>MemorySection</code> (BSWMD), die erst über das Modul <code>MemMap</code> im ECU-Extract an die jeweilige Toolchain (Tasking, HighTec, Green Hills, Wind River etc.) gebunden werden.</li>\n</ul>"}], "trans": [{"from": "FIG-419ee463deff4e8a", "to": "FIG-caba56490913b701", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Neues Eingangs-Work-Product:</strong> <code>Atomic Software Component Implementation</code> hinzugefügt als <code>«input»</code> für <code>Configure Memmap Allocation</code> (<code>+MemorySections</code> [0..*]) und <code>Generate SWC Memory Mapping Header</code> (<code>+MemorySections</code> [1]).</li>\n<li><strong>Geänderte Eingänge für <code>Generate BSW Memory Mapping Header</code>:</strong> Zusätzlicher <code>«input»</code> <code>+DependencyOnArtifact</code> [1] aus <code>Basic Software Module Implementation Description</code>. Die Kardinalität des Eingangs <code>+MemorySections</code> von <code>Basic Software Module Implementation Description</code> wurde von [1..*] auf [1] präzisiert.</li>\n<li><strong>Header-Artefaktbenennung:</strong></li>\n<li><code>+SWC_memmap.h</code> [1] umbenannt zu <code>+SWC_MemMap</code> [1].</li>\n<li><code>+memmap.h</code> [1] umbenannt zu <code>+BSW_MemMap</code> [1].</li>\n<li><strong>Scope-Beschreibungen (Notizen) redaktionell angepasst:</strong></li>\n<li><code>per compiler platform</code> -> <code>Per compiler platform</code></li>\n<li><code>per build environment</code> (bei <code>Configure Memmap Allocation</code>) -> <code>Per build environment.</code></li>\n<li><code>per component and buld environment</code> -> <code>Per component and build environment.</code></li>\n<li><code>per build environment</code> (bei <code>Generate BSW Memory Mapping Header</code>) -> <code>Per BSW module/cluster and build environment.</code></li>\n</ul>"}, {"from": "FIG-caba56490913b701", "to": "FIG-15345da2cd591897", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-15345da2cd591897", "to": "FIG-3fb1182b897b3dfc", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3fb1182b897b3dfc", "to": "FIG-e6c0cf576be2ce12", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Entfall der Notizen:</strong> Die an Aktivitäten angehefteten Notizfelder mit Scope-Angaben (<code>Per compiler platform</code>, <code>Per build environment.</code>, <code>Per component and build environment.</code>, <code>Per BSW module/cluster and build environment.</code>) wurden aus dem Diagramm entfernt.</li>\n</ul>"}, {"from": "FIG-e6c0cf576be2ce12", "to": "FIG-eed4391a0ca78d33", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eed4391a0ca78d33", "to": "FIG-2e56a58265dad43d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2e56a58265dad43d", "to": "FIG-7999552cc1c10d1f", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7999552cc1c10d1f", "to": "FIG-4d1cb71eee4c80ec", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Basic Software Module Implementation Description:</strong></li>\n<li>Tippfehler korrigiert: Beschriftung <code>+DependencyOnArtifac 1</code> zu <code>+DependencyOnArtifact 1</code> korrigiert.</li>\n<li><strong>Typografischer Zeilenumbruch:</strong></li>\n<li>Modul- und Aktivitätsbezeichnungen im Layout neu umgebrochen (u. a. <code>Generate BSW Memory Mapping Header</code>, <code>Compile Atomic Software Component</code>).</li>\n</ul>"}, {"from": "FIG-4d1cb71eee4c80ec", "to": "FIG-335b31c7d002a9e6", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Layout- und Routing-Überarbeitung:</strong></li>\n<li>Vollständige Neuanordnung der Artefakt- und Aktivitätsknoten sowie Entflechtung der Verbindungslinien.</li>\n<li>Artefakt <code>Basic Software Module Implementation Description</code> von der rechten Bildseite nach links unten verschoben.</li>\n<li>Pfeilführungen und Beschriftungsplatzierungen (<code>«input»</code>, <code>«output»</code>, Multiplizitäten) neu geroutet und typografisch bereinigt.</li>\n</ul>"}]};
